package bridge

import (
	_ "embed"
	"encoding/json"
	"testing"

	matteralarm "github.com/SukramJ/go-fabric/cluster/alarm"
	clusterwire "github.com/SukramJ/go-fabric/cluster/wire"
)

// application-wire-fixtures.json holds matter.js's own encodings of the
// FanControl Step request and of the SmokeCoAlarm and
// PumpConfigurationAndControl event payloads (TlvOfModel(element)),
// generated by notes/parity/matter/generate-application-fixtures.ts.
//
//go:embed testdata/application-wire-fixtures.json
var applicationWireFixturesJSON []byte

type applicationWireFixture struct {
	Label   string `json:"label"`
	Kind    string `json:"kind"`
	Cluster uint32 `json:"cluster"`
	Element string `json:"element"`
	Fixture struct {
		Direction          uint8 `json:"direction"`
		Wrap               *bool `json:"wrap"`
		LowestOff          *bool `json:"lowestOff"`
		AlarmSeverityLevel uint8 `json:"alarmSeverityLevel"`
	} `json:"fixture"`
	BytesHex string `json:"bytesHex"`
}

// TestApplicationPayloadsMatchMatterJS decodes every Step payload
// matter.js encodes into the request the fan server receives — with the
// element defaults filled in for an absent optional field — and encodes
// every event payload the alarm and pump servers emit into the bytes
// matter.js produces for it.
func TestApplicationPayloadsMatchMatterJS(t *testing.T) {
	t.Parallel()
	var fixtures []applicationWireFixture
	if err := json.Unmarshal(applicationWireFixturesJSON, &fixtures); err != nil || len(fixtures) == 0 {
		t.Fatalf("application-wire-fixtures.json: %v (%d entries)", err, len(fixtures))
	}
	for _, f := range fixtures {
		t.Run(f.Label, func(t *testing.T) {
			t.Parallel()
			switch {
			case f.Kind == "commands" && f.Element == "Step":
				got, ok := decodeCommandFields(t, f.Cluster, clusterwire.FanControlCmdStep, f.BytesHex).(clusterwire.FanStepRequest)
				want := clusterwire.FanStepRequest{Direction: f.Fixture.Direction, LowestOff: true}
				if f.Fixture.Wrap != nil {
					want.Wrap = *f.Fixture.Wrap
				}
				if f.Fixture.LowestOff != nil {
					want.LowestOff = *f.Fixture.LowestOff
				}
				if !ok || got != want {
					t.Fatalf("decoded %+v, want %+v", got, want)
				}
			case f.Kind == "events" && f.Cluster == matteralarm.ClusterID && f.Fixture.AlarmSeverityLevel != 0:
				ev := matteralarm.AlarmSeverityEvent{AlarmSeverityLevel: matteralarm.AlarmState(f.Fixture.AlarmSeverityLevel)}
				if got := encodeValue(t, ev); got != f.BytesHex {
					t.Fatalf("encoded %s, matter.js %s", got, f.BytesHex)
				}
			case f.Kind == "events":
				if got := encodeValue(t, clusterwire.FieldlessEvent{}); got != f.BytesHex {
					t.Fatalf("encoded %s, matter.js %s", got, f.BytesHex)
				}
			default:
				t.Fatalf("unhandled fixture %s %s", f.Kind, f.Element)
			}
		})
	}
}
